{
  "gate_token": "aq34EhCS5SllZGGlKo7ggA",
  "title": "The Mirror Road Home",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined capital at dusk.",
      "visual_description": "A windswept hilltop overlooking a shattered skyline of broken spires; an ink-stained coat flares in the wind as a brass compass spins above a parchment.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp flickers awake with a warning.",
      "visual_description": "A battered oil lamp held at arm's length, its single flame-eye blinking open in the blue twilight, casting a long anxious shadow across the map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox sniffs the wind near the castle gates.",
      "visual_description": "A small clockwork fox with glowing blue glass eyes perched on a fallen statue before iron gates twisted shut; key-wind tail ticking softly.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives through a cracked shop window.",
      "visual_description": "A figure in a clear diving helmet steps out of a shattered storefront pane as if surfacing from water, coat catching firelight from distant ruins.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They slip past an armored patrol marching the boulevard.",
      "visual_description": "Four crouched silhouettes pressed against a mossy wall as torchlight and clanking metal pass beyond a row of broken columns.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Old royal banners hang in the abandoned square.",
      "visual_description": "Tattered crimson banners drift over a cracked fountain; Tin Fox sits at attention, ears twitching, while the oracle lamp throws golden light over rusted heraldry.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp warns of a cursed tower ahead.",
      "visual_description": "A leaning black tower wreathed in violet mist; the flame-eye widens, projecting jagged warning runes onto cobblestones.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Frightened townspeople flee past, but the team holds course.",
      "visual_description": "Blurred figures rush by in the background while Mara plants her compass like an anchor, ink coat snapping, eyes fixed forward.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "They find the sleeping tax collector slumped in a doorway.",
      "visual_description": "A plump official snoring against a ledger pillow, stamped papers fluttering from his sleeves; Tin Fox pokes his boot suspiciously.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara searches the official's papers for the captive's location.",
      "visual_description": "Candlelight on smudged seals and a hand-drawn cell diagram; the tax collector mumbles in his sleep, drooling on a brass stamp.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver slips through a tall mirror in a ballroom.",
      "visual_description": "A grand cracked mirror ripples like a vertical pool; the diver's coat reflects scattered chandelier crystals as he disappears into silver.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, a magic door pulses with locking sigils.",
      "visual_description": "A heavy oak door covered in spinning chalk circles; the diver presses a gloved palm to the wood while light leaks around its edges.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox picks the lock with a delicate tail-key.",
      "visual_description": "The small fox upside-down, key-tail inserted into a rune-etched keyhole; gears in its flank visible, blue eyes narrowed in concentration.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Rumors of a great winged beast rumble overhead.",
      "visual_description": "Through a shattered ceiling, an enormous shadow with serpentine wings sweeps across a smoke-stained moon; everyone freezes mid-step.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The oracle lamp dims itself to hide their light.",
      "visual_description": "The flame-eye squeezes shut to a pinpoint; the team is washed in deep blue, holding still beneath an arched window as scales glitter past outside.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They drag the sleeping official along as unwilling cargo.",
      "visual_description": "The tax collector slung in a cargo net between Mara and Glass Diver, ledger still clutched to his chest, snoring through the danger.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The team sprints onto the long stone bridge at dawn.",
      "visual_description": "A narrow bridge over a misted gorge; the rescuers bolt across as the first pale sunlight gilds the ruined skyline behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far cliff, Mara marks the map as 'rescued.'",
      "visual_description": "A windy bluff above clouds; the cartographer presses a small wax seal onto her parchment while Tin Fox watches the bridge collapse in the distance and the lamp glows warm gold.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

